import { runSql, withClient } from "@/server/db";
import { getCommon } from "@/server/sqlfiles";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

// Lesson 12: vector tiles generated by PostGIS (sql/common.sql, block "tile").
export async function GET(_req: Request, ctx: { params: Promise<{ z: string; x: string; y: string }> }) {
  const p = await ctx.params;
  const z = Number(p.z);
  const x = Number(p.x);
  const y = Number(String(p.y).replace(/\.pbf$|\.mvt$/, ""));
  const max = 2 ** z;
  if (![z, x, y].every(Number.isInteger) || z < 0 || z > 22 || x < 0 || y < 0 || x >= max || y >= max) {
    return new Response("Bad tile", { status: 400 });
  }
  try {
    const tile = await withClient(async (client) => {
      const out = await runSql(client, "tile", getCommon("tile"), { z, x, y }, []);
      return out.raw[0]?.tile as Buffer | undefined;
    });
    return new Response(tile && tile.length ? new Uint8Array(tile) : null, {
      status: tile && tile.length ? 200 : 204,
      headers: { "Content-Type": "application/vnd.mapbox-vector-tile", "Cache-Control": "no-store" },
    });
  } catch (e) {
    return new Response((e as Error).message, { status: 500 });
  }
}
